Object.assign(I18N.ar,{do_pick:"أقرأ ملفات المشروع",gh_repo:"المشروع (مستودع GitHub)",gh_none:"بدون مستودع – إجابة نصية فقط",gh_new:"＋ مستودع جديد…",gh_newname:"اسم المستودع الجديد (حروف، أرقام، - . _)",gh_bad_name:"أدخل اسمًا صالحًا للمستودع الجديد.",gh_need_token:"أضف رمز GitHub في الإعدادات ليتمكن الفريق من بناء مشاريع حقيقية في مستودعاتك.",gh_p:"يعمل الفريق في مستودعاتك على فرع خاص (nrn/…) ويفتح طلب سحب. لا يصل شيء إلى main حتى تدمجه أنت. استخدم رمزًا دقيقًا محدودًا بالمستودعات المختارة مع: Contents قراءة وكتابة، Pull requests قراءة وكتابة، Metadata قراءة. لا تُرسل الملفات السرية (.env، المفاتيح) إلى الذكاء الاصطناعي أبدًا.",gh_token:"رمز GitHub",gh_ok:"✔ متصل بـ GitHub باسم {u}",gh_created:"تم إنشاء المستودع {r}",gh_reading:"تمت قراءة {n} ملفات من {r}",gh_commit:"تم إيداع {n} ملفات في الفرع {b}",gh_pr:"تم فتح طلب السحب: {u}",gh_nochanges:"لم يُجرِ الفريق أي تغييرات على الملفات.",gh_open_pr:"افتح PR #{n}",gh_merge:"دمج",gh_merge_confirm:"دمج PR #{n} في {b}؟ هذا يغيّر مشروعك الحقيقي.",gh_merged:"تم دمج PR #{n} ✔",gh_continue:"واصل البناء",gh_cont_on:"المتابعة على الفرع {b}",gh_cancel:"ابدأ من جديد بدلًا من ذلك",gh_files:"الملفات المعدّلة",gh_badjson:"إجابة {n} لم تتضمن تغييرات ملفات صالحة (JSON)."});
Object.assign(I18N.es,{do_pick:"leyendo los archivos del proyecto",gh_repo:"Proyecto (repo de GitHub)",gh_none:"Sin repo – solo respuesta de texto",gh_new:"＋ Nuevo repo…",gh_newname:"Nombre del nuevo repo (letras, dígitos, - . _)",gh_bad_name:"Escribe un nombre válido para el nuevo repo.",gh_need_token:"Añade un token de GitHub en Ajustes para que el equipo cree proyectos reales en tus repos.",gh_p:"El equipo trabaja en tus repos en su propia rama (nrn/…) y abre un pull request. Nada llega a main hasta que tú lo fusionas. Usa un token fine-grained limitado a repos elegidos con: Contents lectura y escritura, Pull requests lectura y escritura, Metadata lectura. Los archivos secretos (.env, claves) nunca se envían a la IA.",gh_token:"Token de GitHub",gh_ok:"✔ Conectado a GitHub como {u}",gh_created:"Repo {r} creado",gh_reading:"Leídos {n} archivos de {r}",gh_commit:"{n} archivos confirmados en la rama {b}",gh_pr:"Pull request abierto: {u}",gh_nochanges:"El equipo no hizo cambios en archivos.",gh_open_pr:"Abrir PR #{n}",gh_merge:"Fusionar",gh_merge_confirm:"¿Fusionar PR #{n} en {b}? Esto cambia tu proyecto real.",gh_merged:"PR #{n} fusionado ✔",gh_continue:"Seguir construyendo",gh_cont_on:"Continuando en la rama {b}",gh_cancel:"Empezar de cero",gh_files:"Archivos modificados",gh_badjson:"La respuesta de {n} no contenía cambios de archivos válidos (JSON)."});
