Object.assign(I18N.zh,{do_pick:"在读取项目文件",gh_repo:"项目（GitHub 仓库）",gh_none:"不使用仓库 – 仅文本回答",gh_new:"＋ 新建仓库…",gh_newname:"新仓库名称（字母、数字、- . _）",gh_bad_name:"请输入有效的新仓库名称。",gh_need_token:"在设置中添加 GitHub 令牌，团队即可在你的仓库中构建真实项目。",gh_p:"团队在你的仓库中使用自己的分支（nrn/…）工作并创建拉取请求。在你合并之前，main 不会有任何改动。请使用仅限所选仓库的细粒度令牌，权限：Contents 读写、Pull requests 读写、Metadata 只读。机密文件（.env、密钥）绝不会发送给 AI。",gh_token:"GitHub 令牌",gh_ok:"✔ 已以 {u} 身份连接 GitHub",gh_created:"已创建仓库 {r}",gh_reading:"已从 {r} 读取 {n} 个文件",gh_commit:"已向分支 {b} 提交 {n} 个文件",gh_pr:"已创建拉取请求：{u}",gh_nochanges:"团队没有修改任何文件。",gh_open_pr:"打开 PR #{n}",gh_merge:"合并",gh_merge_confirm:"将 PR #{n} 合并到 {b}？这会修改你的真实项目。",gh_merged:"PR #{n} 已合并 ✔",gh_continue:"继续开发",gh_cont_on:"继续在分支 {b} 上开发",gh_cancel:"改为重新开始",gh_files:"已修改的文件",gh_badjson:"{n} 的回答中没有有效的文件修改（JSON）。"});
