Object.assign(I18N.en,{"roles_assign": "{l} assigns the roles: {s} searches through the project, {h} hunts for errors, {f} fixes them.", "step_scout": "{n} is searching through the whole project…", "handoff": "{a} → {b}: {m}", "step_hunt": "{n} is hunting for errors…", "hunt_done": "{a} → {b}: I found {c} things – {k} can be fixed today.", "do_scout": "searching through the project", "do_watch": "reading the web page for your search", "do_verify": "double-checking the matches", "w_proj": "Watch: {n}", "w_started": "{n} starts the daily watch: {q}", "w_assign": "{l} gives the search to {s}; {h} will double-check the matches.", "w_fetch": "{n} opens {u}…", "w_read": "{n} reads the page ({c} links)…", "w_cand": "I found {c} candidate(s).", "w_verify": "{n} checks the candidates against every criterion…", "w_found_msg": "Good news! We found {n} match(es) for “{q}”:", "w_none_today": "Today we found nothing matching “{q}”, unfortunately.", "w_found_short": "Found {n} match(es)!", "w_none_short": "Nothing found today.", "w_found_log": "{w}: found {n} match(es)", "w_none_log": "{w}: nothing found today", "w_err_msg": "I could not complete today's watch “{w}”: {e}", "w_h": "Daily watches", "w_p": "Give the team a search to run every day. Tomas hands it to the team and always reports back – with a match, or with “nothing found today”.", "w_blocket": "The team reads normal web pages and follows each site's robots.txt. Sites that forbid bots (such as blocket.se, which requires written permission) are not fetched – use the site's own saved-search alerts there.", "w_empty": "No watches yet.", "w_name": "Name", "w_name_ph": "e.g. Red Volvo 1990", "w_time": "Every day at", "w_url": "Page to check (search results address)", "w_query": "What should the team look for?", "w_query_ph": "e.g. red Volvo from 1990, automatic gearbox", "w_hint": "The page is read by the server; the model only reads text, so any model works.", "w_add": "Add watch", "w_run": "Run now", "w_del": "Remove", "w_del_confirm": "Remove the watch “{n}”?", "w_never": "Not run yet.", "w_last": "Last run", "w_bad_url": "Enter a full web address starting with http:// or https://", "w_need_query": "Describe what the team should look for.", "bulk_h": "Same model for the whole team", "bulk_p": "Pick a model (for example a free Gemma) and apply it to everyone at once.", "bulk_apply": "Apply to everyone", "bulk_done": "{n} employees now use {m}"});
Object.assign(I18N.sv,{"roles_assign": "{l} fördelar rollerna: {s} söker igenom projektet, {h} letar fel och {f} rättar dem.", "step_scout": "{n} söker igenom hela projektet…", "handoff": "{a} → {b}: {m}", "step_hunt": "{n} letar efter fel…", "hunt_done": "{a} → {b}: Jag hittade {c} saker – {k} går att rätta idag.", "do_scout": "söker igenom projektet", "do_watch": "läser webbsidan för din sökning", "do_verify": "dubbelkollar träffarna", "w_proj": "Bevakning: {n}", "w_started": "{n} startar dagens bevakning: {q}", "w_assign": "{l} ger sökningen till {s}; {h} dubbelkollar träffarna.", "w_fetch": "{n} öppnar {u}…", "w_read": "{n} läser sidan ({c} länkar)…", "w_cand": "Jag hittade {c} kandidat(er).", "w_verify": "{n} kontrollerar kandidaterna mot alla kriterier…", "w_found_msg": "Goda nyheter! Vi hittade {n} träff(ar) på ”{q}”:", "w_none_today": "Idag hittade vi ingen träff på ”{q}” tyvärr.", "w_found_short": "Hittade {n} träff(ar)!", "w_none_short": "Hittade inget idag.", "w_found_log": "{w}: hittade {n} träff(ar)", "w_none_log": "{w}: hittade inget idag", "w_err_msg": "Jag kunde inte slutföra dagens bevakning ”{w}”: {e}", "w_h": "Dagliga bevakningar", "w_p": "Ge teamet en sökning att köra varje dag. Tomas ger den vidare och rapporterar alltid tillbaka – med en träff, eller med ”hittade inget idag”.", "w_blocket": "Teamet läser vanliga webbsidor och följer varje sajts robots.txt. Sajter som förbjuder robotar (som blocket.se, som kräver skriftligt tillstånd) hämtas inte – använd sajtens egna sparade sökningar med notiser där.", "w_empty": "Inga bevakningar än.", "w_name": "Namn", "w_name_ph": "t.ex. Röd Volvo 1990", "w_time": "Varje dag klockan", "w_url": "Sida att kolla (adress till sökresultat)", "w_query": "Vad ska teamet leta efter?", "w_query_ph": "t.ex. röd Volvo från 1990, automatlåda", "w_hint": "Servern läser sidan; modellen läser bara text, så vilken modell som helst fungerar.", "w_add": "Lägg till bevakning", "w_run": "Kör nu", "w_del": "Ta bort", "w_del_confirm": "Ta bort bevakningen ”{n}”?", "w_never": "Inte körd än.", "w_last": "Senast", "w_bad_url": "Skriv en hel webbadress som börjar med http:// eller https://", "w_need_query": "Beskriv vad teamet ska leta efter.", "bulk_h": "Samma modell till hela teamet", "bulk_p": "Välj en modell (till exempel en gratis Gemma) och använd den på alla på en gång.", "bulk_apply": "Använd på alla", "bulk_done": "{n} anställda kör nu {m}"});
Object.assign(I18N.tr,{"roles_assign": "{l} rolleri dağıtıyor: {s} projeyi tarıyor, {h} hataları arıyor, {f} düzeltiyor.", "step_scout": "{n} tüm projeyi tarıyor…", "handoff": "{a} → {b}: {m}", "step_hunt": "{n} hataları arıyor…", "hunt_done": "{a} → {b}: {c} şey buldum – {k} tanesi bugün düzeltilebilir.", "do_scout": "projeyi tarıyorum", "do_watch": "aramanız için web sayfasını okuyorum", "do_verify": "eşleşmeleri iki kez kontrol ediyorum", "w_proj": "İzleme: {n}", "w_started": "{n} günlük izlemeyi başlatıyor: {q}", "w_assign": "{l} aramayı {s} kişisine veriyor; {h} eşleşmeleri iki kez kontrol edecek.", "w_fetch": "{n} {u} sitesini açıyor…", "w_read": "{n} sayfayı okuyor ({c} bağlantı)…", "w_cand": "{c} aday buldum.", "w_verify": "{n} adayları tüm kriterlere göre kontrol ediyor…", "w_found_msg": "Güzel haber! “{q}” için {n} eşleşme bulduk:", "w_none_today": "Bugün “{q}” için maalesef eşleşme bulamadık.", "w_found_short": "{n} eşleşme bulundu!", "w_none_short": "Bugün bir şey bulunamadı.", "w_found_log": "{w}: {n} eşleşme bulundu", "w_none_log": "{w}: bugün bir şey bulunamadı", "w_err_msg": "Bugünkü “{w}” izlemesini tamamlayamadım: {e}", "w_h": "Günlük izlemeler", "w_p": "Ekibe her gün çalıştırılacak bir arama verin. Tomas bunu ekibe iletir ve her zaman rapor verir – bir eşleşmeyle ya da “bugün bir şey bulunamadı” diyerek.", "w_blocket": "Ekip normal web sayfalarını okur ve her sitenin robots.txt kurallarına uyar. Botları yasaklayan siteler (yazılı izin isteyen blocket.se gibi) çekilmez – orada sitenin kendi kayıtlı arama bildirimlerini kullanın.", "w_empty": "Henüz izleme yok.", "w_name": "Ad", "w_name_ph": "örn. Kırmızı Volvo 1990", "w_time": "Her gün saat", "w_url": "Kontrol edilecek sayfa (arama sonuçları adresi)", "w_query": "Ekip neyi arasın?", "w_query_ph": "örn. 1990 model kırmızı Volvo, otomatik vites", "w_hint": "Sayfayı sunucu okur; model yalnızca metni okur, bu yüzden her model çalışır.", "w_add": "İzleme ekle", "w_run": "Şimdi çalıştır", "w_del": "Kaldır", "w_del_confirm": "“{n}” izlemesi kaldırılsın mı?", "w_never": "Henüz çalıştırılmadı.", "w_last": "Son çalışma", "w_bad_url": "http:// veya https:// ile başlayan tam bir web adresi girin", "w_need_query": "Ekibin ne arayacağını açıklayın.", "bulk_h": "Tüm ekip için aynı model", "bulk_p": "Bir model seçin (örneğin ücretsiz bir Gemma) ve herkese bir kerede uygulayın.", "bulk_apply": "Herkese uygula", "bulk_done": "{n} çalışan artık {m} kullanıyor"});
Object.assign(I18N.ar,{"roles_assign": "{l} يوزّع الأدوار: {s} يبحث في المشروع، و{h} يبحث عن الأخطاء، و{f} يصلحها.", "step_scout": "{n} يبحث في المشروع بالكامل…", "handoff": "{a} ← {b}: {m}", "step_hunt": "{n} يبحث عن الأخطاء…", "hunt_done": "{a} ← {b}: وجدت {c} أمورًا – يمكن إصلاح {k} منها اليوم.", "do_scout": "أبحث في المشروع", "do_watch": "أقرأ صفحة الويب لبحثك", "do_verify": "أتحقق مرة أخرى من النتائج", "w_proj": "مراقبة: {n}", "w_started": "{n} يبدأ مراقبة اليوم: {q}", "w_assign": "{l} يعطي البحث إلى {s}؛ و{h} سيتحقق من النتائج مرة أخرى.", "w_fetch": "{n} يفتح {u}…", "w_read": "{n} يقرأ الصفحة ({c} روابط)…", "w_cand": "وجدت {c} مرشح(ين).", "w_verify": "{n} يفحص المرشحين وفق كل المعايير…", "w_found_msg": "أخبار سارة! وجدنا {n} نتيجة مطابقة لـ «{q}»:", "w_none_today": "لم نجد اليوم أي نتيجة مطابقة لـ «{q}» للأسف.", "w_found_short": "تم العثور على {n} نتيجة!", "w_none_short": "لم نجد شيئًا اليوم.", "w_found_log": "{w}: تم العثور على {n} نتيجة", "w_none_log": "{w}: لم نجد شيئًا اليوم", "w_err_msg": "لم أتمكن من إكمال مراقبة اليوم «{w}»: {e}", "w_h": "المراقبات اليومية", "w_p": "أعطِ الفريق بحثًا ينفّذه كل يوم. يسلّمه توماس للفريق ويبلغك دائمًا – بنتيجة أو بعبارة «لم نجد شيئًا اليوم».", "w_blocket": "يقرأ الفريق صفحات الويب العادية ويتبع ملف robots.txt لكل موقع. المواقع التي تمنع الروبوتات (مثل blocket.se الذي يتطلب إذنًا كتابيًا) لا تُجلب – استخدم تنبيهات البحث المحفوظ في الموقع نفسه.", "w_empty": "لا توجد مراقبات بعد.", "w_name": "الاسم", "w_name_ph": "مثال: فولفو حمراء 1990", "w_time": "كل يوم الساعة", "w_url": "الصفحة المراد فحصها (عنوان نتائج البحث)", "w_query": "عمَّ يجب أن يبحث الفريق؟", "w_query_ph": "مثال: فولفو حمراء موديل 1990 بناقل حركة أوتوماتيكي", "w_hint": "يقرأ الخادم الصفحة؛ والنموذج يقرأ النص فقط، لذلك يعمل أي نموذج.", "w_add": "إضافة مراقبة", "w_run": "شغّل الآن", "w_del": "إزالة", "w_del_confirm": "إزالة المراقبة «{n}»؟", "w_never": "لم تُشغَّل بعد.", "w_last": "آخر تشغيل", "w_bad_url": "أدخل عنوان ويب كاملًا يبدأ بـ http:// أو https://", "w_need_query": "صف ما يجب أن يبحث عنه الفريق.", "bulk_h": "نفس النموذج لكل الفريق", "bulk_p": "اختر نموذجًا (مثل Gemma مجاني) وطبّقه على الجميع دفعة واحدة.", "bulk_apply": "طبّق على الجميع", "bulk_done": "{n} موظفين يستخدمون الآن {m}"});
Object.assign(I18N.es,{"roles_assign": "{l} reparte los roles: {s} busca por todo el proyecto, {h} caza errores y {f} los arregla.", "step_scout": "{n} está recorriendo todo el proyecto…", "handoff": "{a} → {b}: {m}", "step_hunt": "{n} está cazando errores…", "hunt_done": "{a} → {b}: He encontrado {c} cosas – {k} se pueden arreglar hoy.", "do_scout": "recorriendo el proyecto", "do_watch": "leyendo la página web para tu búsqueda", "do_verify": "comprobando de nuevo las coincidencias", "w_proj": "Vigilancia: {n}", "w_started": "{n} inicia la vigilancia diaria: {q}", "w_assign": "{l} da la búsqueda a {s}; {h} comprobará las coincidencias.", "w_fetch": "{n} abre {u}…", "w_read": "{n} lee la página ({c} enlaces)…", "w_cand": "He encontrado {c} candidato(s).", "w_verify": "{n} comprueba los candidatos con todos los criterios…", "w_found_msg": "¡Buenas noticias! Hemos encontrado {n} coincidencia(s) para «{q}»:", "w_none_today": "Hoy no hemos encontrado nada para «{q}», lo sentimos.", "w_found_short": "¡{n} coincidencia(s) encontrada(s)!", "w_none_short": "Hoy no se encontró nada.", "w_found_log": "{w}: {n} coincidencia(s)", "w_none_log": "{w}: nada encontrado hoy", "w_err_msg": "No pude completar la vigilancia de hoy «{w}»: {e}", "w_h": "Vigilancias diarias", "w_p": "Da al equipo una búsqueda para ejecutar cada día. Tomas se la pasa al equipo e informa siempre – con una coincidencia o con «hoy no se encontró nada».", "w_blocket": "El equipo lee páginas web normales y respeta el robots.txt de cada sitio. Los sitios que prohíben bots (como blocket.se, que exige permiso escrito) no se consultan – usa las alertas de búsqueda guardada del propio sitio.", "w_empty": "Aún no hay vigilancias.", "w_name": "Nombre", "w_name_ph": "p. ej. Volvo rojo 1990", "w_time": "Cada día a las", "w_url": "Página a revisar (dirección de resultados)", "w_query": "¿Qué debe buscar el equipo?", "w_query_ph": "p. ej. Volvo rojo de 1990, cambio automático", "w_hint": "El servidor lee la página; el modelo solo lee texto, así que sirve cualquier modelo.", "w_add": "Añadir vigilancia", "w_run": "Ejecutar ahora", "w_del": "Quitar", "w_del_confirm": "¿Quitar la vigilancia «{n}»?", "w_never": "Aún no ejecutada.", "w_last": "Última vez", "w_bad_url": "Escribe una dirección web completa que empiece por http:// o https://", "w_need_query": "Describe qué debe buscar el equipo.", "bulk_h": "El mismo modelo para todo el equipo", "bulk_p": "Elige un modelo (por ejemplo un Gemma gratuito) y aplícalo a todos a la vez.", "bulk_apply": "Aplicar a todos", "bulk_done": "{n} empleados usan ahora {m}"});
Object.assign(I18N.it,{"roles_assign": "{l} assegna i ruoli: {s} esplora il progetto, {h} cerca gli errori e {f} li corregge.", "step_scout": "{n} sta esplorando tutto il progetto…", "handoff": "{a} → {b}: {m}", "step_hunt": "{n} sta cercando gli errori…", "hunt_done": "{a} → {b}: Ho trovato {c} cose – {k} si possono correggere oggi.", "do_scout": "esplorando il progetto", "do_watch": "leggendo la pagina web per la tua ricerca", "do_verify": "ricontrollando le corrispondenze", "w_proj": "Monitoraggio: {n}", "w_started": "{n} avvia il monitoraggio di oggi: {q}", "w_assign": "{l} affida la ricerca a {s}; {h} ricontrollerà le corrispondenze.", "w_fetch": "{n} apre {u}…", "w_read": "{n} legge la pagina ({c} link)…", "w_cand": "Ho trovato {c} candidato/i.", "w_verify": "{n} verifica i candidati su ogni criterio…", "w_found_msg": "Buone notizie! Abbiamo trovato {n} risultato/i per «{q}»:", "w_none_today": "Oggi non abbiamo trovato nulla per «{q}», purtroppo.", "w_found_short": "Trovato/i {n} risultato/i!", "w_none_short": "Oggi non è stato trovato nulla.", "w_found_log": "{w}: {n} risultato/i", "w_none_log": "{w}: nulla trovato oggi", "w_err_msg": "Non sono riuscito a completare il monitoraggio di oggi «{w}»: {e}", "w_h": "Monitoraggi giornalieri", "w_p": "Dai al team una ricerca da eseguire ogni giorno. Tomas la passa al team e riferisce sempre – con un risultato o con «oggi non è stato trovato nulla».", "w_blocket": "Il team legge normali pagine web e rispetta il robots.txt di ogni sito. I siti che vietano i bot (come blocket.se, che richiede un permesso scritto) non vengono consultati – usa gli avvisi di ricerca salvata del sito stesso.", "w_empty": "Nessun monitoraggio ancora.", "w_name": "Nome", "w_name_ph": "es. Volvo rossa 1990", "w_time": "Ogni giorno alle", "w_url": "Pagina da controllare (indirizzo dei risultati)", "w_query": "Cosa deve cercare il team?", "w_query_ph": "es. Volvo rossa del 1990, cambio automatico", "w_hint": "La pagina la legge il server; il modello legge solo testo, quindi va bene qualsiasi modello.", "w_add": "Aggiungi monitoraggio", "w_run": "Esegui ora", "w_del": "Rimuovi", "w_del_confirm": "Rimuovere il monitoraggio «{n}»?", "w_never": "Non ancora eseguito.", "w_last": "Ultima volta", "w_bad_url": "Inserisci un indirizzo web completo che inizi con http:// o https://", "w_need_query": "Descrivi cosa deve cercare il team.", "bulk_h": "Stesso modello per tutto il team", "bulk_p": "Scegli un modello (ad esempio un Gemma gratuito) e applicalo a tutti in una volta.", "bulk_apply": "Applica a tutti", "bulk_done": "{n} dipendenti usano ora {m}"});
Object.assign(I18N.fr,{"roles_assign": "{l} répartit les rôles : {s} parcourt le projet, {h} traque les erreurs et {f} les corrige.", "step_scout": "{n} parcourt tout le projet…", "handoff": "{a} → {b} : {m}", "step_hunt": "{n} traque les erreurs…", "hunt_done": "{a} → {b} : J'ai trouvé {c} points – {k} peuvent être corrigés aujourd'hui.", "do_scout": "je parcours le projet", "do_watch": "je lis la page web pour votre recherche", "do_verify": "je revérifie les résultats", "w_proj": "Veille : {n}", "w_started": "{n} lance la veille du jour : {q}", "w_assign": "{l} confie la recherche à {s} ; {h} revérifiera les résultats.", "w_fetch": "{n} ouvre {u}…", "w_read": "{n} lit la page ({c} liens)…", "w_cand": "J'ai trouvé {c} candidat(s).", "w_verify": "{n} vérifie les candidats sur chaque critère…", "w_found_msg": "Bonne nouvelle ! Nous avons trouvé {n} résultat(s) pour « {q} » :", "w_none_today": "Aujourd'hui, nous n'avons rien trouvé pour « {q} », malheureusement.", "w_found_short": "{n} résultat(s) trouvé(s) !", "w_none_short": "Rien trouvé aujourd'hui.", "w_found_log": "{w} : {n} résultat(s)", "w_none_log": "{w} : rien trouvé aujourd'hui", "w_err_msg": "Je n'ai pas pu terminer la veille du jour « {w} » : {e}", "w_h": "Veilles quotidiennes", "w_p": "Donnez à l'équipe une recherche à lancer chaque jour. Tomas la transmet à l'équipe et vous répond toujours – avec un résultat ou « rien trouvé aujourd'hui ».", "w_blocket": "L'équipe lit des pages web normales et respecte le robots.txt de chaque site. Les sites qui interdisent les robots (comme blocket.se, qui exige une autorisation écrite) ne sont pas consultés – utilisez les alertes de recherche enregistrée du site.", "w_empty": "Aucune veille pour l'instant.", "w_name": "Nom", "w_name_ph": "ex. Volvo rouge 1990", "w_time": "Chaque jour à", "w_url": "Page à vérifier (adresse des résultats)", "w_query": "Que doit chercher l'équipe ?", "w_query_ph": "ex. Volvo rouge de 1990, boîte automatique", "w_hint": "Le serveur lit la page ; le modèle ne lit que du texte, donc n'importe quel modèle convient.", "w_add": "Ajouter la veille", "w_run": "Lancer maintenant", "w_del": "Supprimer", "w_del_confirm": "Supprimer la veille « {n} » ?", "w_never": "Pas encore lancée.", "w_last": "Dernier passage", "w_bad_url": "Saisissez une adresse web complète commençant par http:// ou https://", "w_need_query": "Décrivez ce que l'équipe doit chercher.", "bulk_h": "Le même modèle pour toute l'équipe", "bulk_p": "Choisissez un modèle (par exemple un Gemma gratuit) et appliquez-le à tous d'un coup.", "bulk_apply": "Appliquer à tous", "bulk_done": "{n} employés utilisent maintenant {m}"});
Object.assign(I18N.zh,{"roles_assign": "{l} 分配角色：{s} 搜索整个项目，{h} 查找错误，{f} 负责修复。", "step_scout": "{n} 正在搜索整个项目…", "handoff": "{a} → {b}：{m}", "step_hunt": "{n} 正在查找错误…", "hunt_done": "{a} → {b}：我发现了 {c} 个问题 – 其中 {k} 个今天可以修复。", "do_scout": "在搜索项目", "do_watch": "在为你的搜索阅读网页", "do_verify": "在再次核对匹配结果", "w_proj": "监控：{n}", "w_started": "{n} 开始今天的监控：{q}", "w_assign": "{l} 把搜索交给 {s}；{h} 会再次核对匹配结果。", "w_fetch": "{n} 正在打开 {u}…", "w_read": "{n} 正在阅读页面（{c} 个链接）…", "w_cand": "我找到了 {c} 个候选。", "w_verify": "{n} 正在按所有条件核对候选…", "w_found_msg": "好消息！我们为“{q}”找到了 {n} 个匹配：", "w_none_today": "很遗憾，今天没有找到与“{q}”匹配的内容。", "w_found_short": "找到 {n} 个匹配！", "w_none_short": "今天没有发现。", "w_found_log": "{w}：找到 {n} 个匹配", "w_none_log": "{w}：今天没有发现", "w_err_msg": "我无法完成今天的监控“{w}”：{e}", "w_h": "每日监控", "w_p": "给团队一个每天运行的搜索任务。Tomas 会交给团队并始终向你汇报 – 要么有匹配，要么告诉你“今天没有发现”。", "w_blocket": "团队读取普通网页并遵守每个网站的 robots.txt。禁止机器人的网站（如需要书面许可的 blocket.se）不会被抓取 – 请使用该网站自带的保存搜索提醒。", "w_empty": "还没有监控。", "w_name": "名称", "w_name_ph": "例如：红色沃尔沃 1990", "w_time": "每天", "w_url": "要检查的页面（搜索结果地址）", "w_query": "团队应该寻找什么？", "w_query_ph": "例如：1990 年的红色沃尔沃，自动挡", "w_hint": "页面由服务器读取；模型只读文本，所以任何模型都可以。", "w_add": "添加监控", "w_run": "立即运行", "w_del": "移除", "w_del_confirm": "移除监控“{n}”吗？", "w_never": "尚未运行。", "w_last": "上次运行", "w_bad_url": "请输入以 http:// 或 https:// 开头的完整网址", "w_need_query": "请描述团队应该寻找什么。", "bulk_h": "全团队使用同一模型", "bulk_p": "选择一个模型（例如免费的 Gemma），一次应用到所有人。", "bulk_apply": "应用到所有人", "bulk_done": "{n} 名员工现在使用 {m}"});
Object.assign(I18N.ja,{"roles_assign": "{l} が役割を割り振ります：{s} がプロジェクト全体を調べ、{h} がエラーを探し、{f} が修正します。", "step_scout": "{n} がプロジェクト全体を調べています…", "handoff": "{a} → {b}：{m}", "step_hunt": "{n} がエラーを探しています…", "hunt_done": "{a} → {b}：{c} 件見つけました – 今日は {k} 件を修正できます。", "do_scout": "プロジェクトを調べています", "do_watch": "検索のためにウェブページを読んでいます", "do_verify": "一致結果を再確認しています", "w_proj": "ウォッチ：{n}", "w_started": "{n} が今日のウォッチを開始：{q}", "w_assign": "{l} が検索を {s} に依頼し、{h} が一致結果を再確認します。", "w_fetch": "{n} が {u} を開いています…", "w_read": "{n} がページを読んでいます（リンク {c} 件）…", "w_cand": "候補を {c} 件見つけました。", "w_verify": "{n} が候補をすべての条件で確認しています…", "w_found_msg": "朗報です！「{q}」に一致するものが {n} 件見つかりました：", "w_none_today": "残念ながら、今日は「{q}」に一致するものは見つかりませんでした。", "w_found_short": "{n} 件見つかりました！", "w_none_short": "今日は見つかりませんでした。", "w_found_log": "{w}：{n} 件見つかりました", "w_none_log": "{w}：今日は見つかりませんでした", "w_err_msg": "今日のウォッチ「{w}」を完了できませんでした：{e}", "w_h": "毎日のウォッチ", "w_p": "チームに毎日実行する検索を依頼します。Tomas がチームに渡し、一致があった場合も「今日は見つかりませんでした」の場合も必ず報告します。", "w_blocket": "チームは通常のウェブページを読み、各サイトの robots.txt に従います。ボットを禁止しているサイト（書面の許可が必要な blocket.se など）は取得しません。そのサイトの保存検索通知を使ってください。", "w_empty": "ウォッチはまだありません。", "w_name": "名前", "w_name_ph": "例：赤いボルボ 1990", "w_time": "毎日", "w_url": "確認するページ（検索結果のアドレス）", "w_query": "チームは何を探しますか？", "w_query_ph": "例：1990 年式の赤いボルボ、オートマ", "w_hint": "ページはサーバーが読み、モデルはテキストだけを読むので、どのモデルでも動きます。", "w_add": "ウォッチを追加", "w_run": "今すぐ実行", "w_del": "削除", "w_del_confirm": "ウォッチ「{n}」を削除しますか？", "w_never": "まだ実行されていません。", "w_last": "前回", "w_bad_url": "http:// または https:// で始まる完全なアドレスを入力してください", "w_need_query": "チームが探すものを説明してください。", "bulk_h": "チーム全員に同じモデル", "bulk_p": "モデル（例：無料の Gemma）を選び、全員に一度に適用します。", "bulk_apply": "全員に適用", "bulk_done": "{n} 人が {m} を使うようになりました"});

