/* reservsamtal (8 repliker) */
Object.assign(I18N.en,{"talk_1": "Hi {b}, do you have a minute? {t}", "talk_2": "Of course, {a}. Tell me more.", "talk_3": "It matters to us, so please be careful and thorough.", "talk_4": "Understood. Should I start with the most important part?", "talk_5": "Yes – begin with what has the biggest impact, then the details.", "talk_6": "Okay. And if something is unclear I will tell you straight away.", "talk_7": "Perfect. Take the time you need, quality beats speed.", "talk_8": "Got it – I'll get started right away!"});
Object.assign(I18N.sv,{"talk_1": "Hej {b}, har du en minut? {t}", "talk_2": "Självklart, {a}. Berätta mer.", "talk_3": "Det är viktigt för oss, så var noggrann och grundlig.", "talk_4": "Uppfattat. Ska jag börja med det viktigaste?", "talk_5": "Ja – börja med det som gör störst skillnad, sedan detaljerna.", "talk_6": "Okej. Och om något är oklart säger jag till direkt.", "talk_7": "Perfekt. Ta den tid du behöver, kvalitet går före fart.", "talk_8": "Jag fixar det – jag sätter igång direkt!"});
Object.assign(I18N.tr,{"talk_1": "Merhaba {b}, bir dakikan var mı? {t}", "talk_2": "Tabii {a}. Biraz daha anlat.", "talk_3": "Bu bizim için önemli, o yüzden dikkatli ve titiz ol.", "talk_4": "Anlaşıldı. En önemli kısımla mı başlayayım?", "talk_5": "Evet – önce en çok fark yaratanla başla, sonra ayrıntılar.", "talk_6": "Tamam. Bir şey belirsizse hemen sana söylerim.", "talk_7": "Harika. İhtiyacın kadar zaman al, kalite hızdan önemli.", "talk_8": "Anladım – hemen başlıyorum!"});
Object.assign(I18N.ar,{"talk_1": "مرحبًا {b}، هل لديك دقيقة؟ {t}", "talk_2": "بالطبع يا {a}. أخبرني بالمزيد.", "talk_3": "هذا مهم لنا، فكن دقيقًا وشاملًا.", "talk_4": "مفهوم. هل أبدأ بأهم جزء؟", "talk_5": "نعم – ابدأ بما له أكبر أثر، ثم التفاصيل.", "talk_6": "حسنًا. وإذا كان هناك شيء غير واضح سأخبرك فورًا.", "talk_7": "ممتاز. خذ الوقت الذي تحتاجه، فالجودة أهم من السرعة.", "talk_8": "تمام – سأبدأ فورًا!"});
Object.assign(I18N.es,{"talk_1": "Hola {b}, ¿tienes un minuto? {t}", "talk_2": "Claro, {a}. Cuéntame más.", "talk_3": "Es importante para nosotros, así que sé cuidadoso y minucioso.", "talk_4": "Entendido. ¿Empiezo por lo más importante?", "talk_5": "Sí: empieza por lo que más impacto tenga y luego los detalles.", "talk_6": "Vale. Y si algo no está claro te lo digo enseguida.", "talk_7": "Perfecto. Tómate el tiempo que necesites, la calidad va antes que la prisa.", "talk_8": "¡Hecho, me pongo manos a la obra ya!"});
Object.assign(I18N.it,{"talk_1": "Ciao {b}, hai un minuto? {t}", "talk_2": "Certo, {a}. Dimmi di più.", "talk_3": "È importante per noi, quindi sii accurato e preciso.", "talk_4": "Capito. Parto dalla parte più importante?", "talk_5": "Sì: inizia da ciò che conta di più, poi i dettagli.", "talk_6": "Ok. E se qualcosa non è chiaro te lo dico subito.", "talk_7": "Perfetto. Prenditi il tempo che serve, la qualità viene prima della fretta.", "talk_8": "Ricevuto, mi metto subito al lavoro!"});
Object.assign(I18N.fr,{"talk_1": "Salut {b}, tu as une minute ? {t}", "talk_2": "Bien sûr, {a}. Dis-m'en plus.", "talk_3": "C'est important pour nous, alors sois soigneux et minutieux.", "talk_4": "Compris. Je commence par le plus important ?", "talk_5": "Oui – commence par ce qui compte le plus, puis les détails.", "talk_6": "D'accord. Et si quelque chose n'est pas clair, je te préviens tout de suite.", "talk_7": "Parfait. Prends le temps qu'il faut, la qualité passe avant la vitesse.", "talk_8": "C'est noté – je m'y mets tout de suite !"});
Object.assign(I18N.zh,{"talk_1": "你好 {b}，有空吗？{t}", "talk_2": "当然，{a}。多说一点。", "talk_3": "这对我们很重要，所以请仔细、全面。", "talk_4": "明白。我先从最重要的部分开始吗？", "talk_5": "对——先做影响最大的，再处理细节。", "talk_6": "好的。如果有不清楚的地方，我会马上告诉你。", "talk_7": "很好。花你需要的时间，质量比速度重要。", "talk_8": "收到——我马上开始！"});
Object.assign(I18N.ja,{"talk_1": "{b}さん、少し時間ありますか？{t}", "talk_2": "もちろんです、{a}さん。詳しく教えてください。", "talk_3": "大事なことなので、丁寧に、しっかりお願いします。", "talk_4": "了解です。一番大事なところから始めればいいですか？", "talk_5": "はい、効果の大きいところから、そのあと細部を。", "talk_6": "わかりました。不明点があればすぐ報告します。", "talk_7": "完璧です。必要な時間をかけてください。速さより質です。", "talk_8": "承知しました。すぐに取りかかります！"});
